import { z } from 'zod'

const ItemSchema = z.object({ id: z.string(), value: z.number() })
const BatchSchema = z.array(ItemSchema).max(100)

export async function POST(request: Request) {
  const body = await request.json()
  const parsed = BatchSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: 'Invalid batch' }, { status: 400 })
  }

ideal_output:
  const results = await Promise.allSettled(
    parsed.data.map(async (item) => {
      const processed = await processItem(item)
      return { id: item.id, result: processed }
    }),
  )

  const responses = results.map((r, i) =>
    r.status === 'fulfilled'
      ? { ok: true, id: parsed.data[i].id, result: r.value.result }
      : { ok: false, id: parsed.data[i].id, error: String(r.reason) },
  )

  return NextResponse.json({ results: responses })
}

async function processItem(item: { id: string; value: number }) {
  return { processedValue: item.value * 2 }
}

