      'X-Forwarded-Proto': request.headers.get('x-forwarded-proto') || 'http',
      'X-Forwarded-Host': request.headers.get('x-forwarded-host') || '',
    },
  })

  const data = await response.json()
  return NextResponse.json(data)
}

