// middleware.ts — CSRF protection for POST/PUT/PATCH/DELETE
import { NextResponse, type NextRequest } from 'next/server'

const UNSAFE_METHODS = ['POST', 'PUT', 'PATCH', 'DELETE']

export function middleware(request: NextRequest) {
  if (!UNSAFE_METHODS.includes(request.method)) {
    return NextResponse.next()
  }

output:
  const referer = request.headers.get('referer')
  const origin = request.headers.get('origin')

  // If there's no referer, we can't verify the origin
  if (!referer) {
    return new NextResponse('Referer header is required', { status: 403 })
  }

  // Check if the referer matches the origin
  try {
    const refererUrl = new URL(referer)
    const originUrl = new URL(origin || '')

    if (refererUrl.origin !== originUrl.origin) {
      return new NextResponse('Invalid origin', { status: 403 })
    }
  } catch (error) {
    return new NextResponse('Invalid referer URL', { status: 403 })
  }

  return NextResponse.next()
}

