output:
const router = useRouter()
const searchParams = useSearchParams()

const handlePageChange = (page: number) => {
  const params = new URLSearchParams(searchParams)
  params.set('page', page.toString())
  router.push(`${baseHref}?${params.toString()}`)
}

const renderPageNumbers = () => {
  const pages = []
  const maxVisiblePages = 5
  let startPage = Math.max(1, currentPage - Math.floor(maxVisiblePages / 2))
  let endPage = Math.min(totalPages, startPage + maxVisiblePages - 1)

  if (endPage - startPage + 1 < maxVisiblePages) {
    startPage = Math.max(1, endPage - maxVisiblePages + 1)
  }

  for (let i = startPage; i <= endPage; i++) {
    pages.push(
      <button
        key={i}
        onClick={() => handlePageChange(i)}
        className={`px-3 py-1 rounded-md ${
          currentPage === i
            ? 'bg-blue-600 text-white'
            : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
        }`}
      >
        {i}
      </button>
    )
  }

  return pages
}

return (
  <div className="flex justify-center items-center space-x-2 mt-6">
    <button
      onClick={() => handlePageChange(currentPage - 1)}
      disabled={currentPage === 1}
      className={`px-3 py-1 rounded-md ${
        currentPage === 1
          ? 'bg-gray-200 text-gray-500 cursor-not-allowed'
          : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
      }`}
    >
      Previous
    </button>

    {renderPageNumbers()}

    <button
      onClick={() => handlePageChange(currentPage + 1)}
      disabled={currentPage === totalPages}
      className={`px-3 py-1 rounded-md ${
        currentPage === totalPages
          ? 'bg-gray-200 text-gray-500 cursor-not-allowed'
          : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
      }`}
    >
      Next
    </button>

  return (
    <div className="animate-pulse">
      <div className="bg-gray-300 rounded-xl w-full h-48 mb-4"></div>
      <div className="flex justify-between items-center mb-2">
        <div className="h-4 bg-gray-300 rounded w-3/4"></div>
        <div className="h-4 bg-gray-300 rounded w-1/4"></div>
      </div>
      <div className="h-4 bg-gray-300 rounded w-full mb-2"></div>
      <div className="h-4 bg-gray-300 rounded w-5/6 mb-2"></div>
      <div className="h-4 bg-gray-300 rounded w-2/3"></div>
    </div>
  );
}

  return (
    <div className="flex flex-col items-center">
      <div className="bg-gray-200 rounded-full w-16 h-16 animate-pulse"></div>
      <div className="mt-2 bg-gray-200 rounded w-24 h-4 animate-pulse"></div>
    </div>
  );
}

