    const { email, role } = data
    const user = await prisma.user.findUnique({
      where: { email },
    })

    if (!user) {
      throw new Error('User not found')
    }

    await prisma.user.update({
      where: { id: user.id },
      data: { role },
    })

    return { success: true }
  }

  if (type === 'remove') {
    const { userId } = data
    await prisma.user.update({
      where: { id: userId },
      data: { role: 'member' },
    })

    return { success: true }
  }
}

