type EventMap = Record<string, unknown>

export class TypedEmitter<E extends EventMap> {

context.prefix:
// Type-safe event emitter — events typed as a record
type EventMap = Record<string, unknown>

export class TypedEmitter<E extends EventMap> {

output:
  private events: Map<keyof E, Array<(data: E[keyof E]) => void>> = new Map()

  on<K extends keyof E>(event: K, callback: (data: E[K]) => void) {
    if (!this.events.has(event)) {
      this.events.set(event, [])
    }
    this.events.get(event)!.push(callback)
  }

  off<K extends keyof E>(event: K, callback: (data: E[K]) => void) {
    if (!this.events.has(event)) return
    const callbacks = this.events.get(event)!
    const index = callbacks.indexOf(callback)
    if (index !== -1) {
      callbacks.splice(index, 1)
    }
  }

  emit<K extends keyof E>(event: K, data: E[K]) {
    if (!this.events.has(event)) return
    for (const callback of this.events.get(event)!) {
      callback(data)
    }
  }
}

